-- Native keybindings; descriptions are available through hyprctl binds.
local d = require("UserConfigs/01-UserDefaults")
hl.bind("SUPER + B", hl.dsp.exec_cmd("xdg-open https://www.google.com"), { description = "open default browser" })
hl.bind("SUPER + A", hl.dsp.exec_cmd(d.scripts .. "/OverviewToggle.sh"), { description = "desktop overview" })
hl.bind("SUPER + Return", hl.dsp.exec_cmd(d.terminal), { description = "Open terminal" })
hl.bind("SUPER + E", hl.dsp.exec_cmd(d.files), { description = "file manager" })
hl.bind("SUPER + D", hl.dsp.exec_cmd("lookapp"), { description = "app launcher" })
hl.bind("SUPER + H", hl.dsp.exec_cmd(d.scripts .. "/KeyHints.sh"), { description = "help / cheat sheet" })
hl.bind("SUPER + ALT + R", hl.dsp.exec_cmd(d.scripts .. "/Refresh.sh"), { description = "refresh bar and menus" })
hl.bind("SUPER + ALT + E", hl.dsp.exec_cmd(d.scripts .. "/RofiEmoji.sh"), { description = "emoji menu" })
hl.bind("SUPER + S", hl.dsp.exec_cmd(d.scripts .. "/RofiSearch.sh"), { description = "web search" })
hl.bind("SUPER + CTRL + S", hl.dsp.exec_cmd("rofi -show window"), { description = "window switcher" })
hl.bind("SUPER + ALT + O", hypr_dots.toggle_blur, { description = "toggle blur" })
hl.bind("SUPER + SHIFT + G", hypr_dots.toggle_game_mode, { description = "toggle game mode" })
hl.bind("SUPER + ALT + L", hypr_dots.toggle_layout, { description = "toggle master/dwindle layout" })
hl.bind("SUPER + ALT + V", hl.dsp.exec_cmd(d.scripts .. "/ClipManager.sh"), { description = "clipboard manager" })
hl.bind("SUPER + SHIFT + F", hl.dsp.window.fullscreen({ mode = "fullscreen" }), { description = "fullscreen" })
