hl.bind("SUPER + SHIFT + Return", hl.dsp.exec_cmd(d.scripts .. "/Dropterminal.sh " .. d.terminal .. ""), { description = "DropDown terminal" })
hl.bind("SUPER + ALT + mouse_down", function() hypr_dots.zoom(2) end, { description = "zoom in" })
hl.bind("SUPER + ALT + mouse_up", function() hypr_dots.zoom(0.5) end, { description = "zoom out" })
hl.bind("SUPER + CTRL + ALT + B", hl.dsp.exec_cmd("pkill -SIGUSR1 waybar"), { description = "toggle waybar on/off" })
