hl.bind("SUPER + M", hl.dsp.layout("splitratio 0.3"), { description = "set split ratio 0.3" })
hl.bind("ALT + tab", function()
    hl.dispatch(hl.dsp.window.cycle_next())
    hl.dispatch(hl.dsp.window.bring_to_top())
end, { description = "cycle next window and bring to top" })
hl.bind("xf86audioraisevolume", hl.dsp.exec_cmd(d.scripts .. "/Volume.sh --inc"), { repeating = true, locked = true, description = "volume up" })
